 campaign_page(request):
    # Check if the user has a cookie set for their preferences
    if request.COOKIES.get('preferences'):
        # Get the user's preferences from the cookie
        preferences = request.COOKIES['preferences']

        # Use the preferences to craft the campaign messaging
        messaging = generate_messaging(preferences)

        # Serve the campaign page with the messaging
        return render(request, 'campaign.html', {'messaging': messaging})
    else:
        # Serve the campaign page without any messaging
        return render(request, 'campaign.html')

def generate_messaging(preferences):
    # Generate the campaign messaging based on the user's preferences
    messaging = []

    # Add messaging for issues that the user might care about
    if preferences.get('education'):
        messaging.append("We are committed to improving education for all students, and we will work to ensure that every student has access to quality education.")

    if preferences.get('healthcare'):
        messaging.append("We are committed to providing affordable and accessible healthcare for all, and we will work to ensure that every citizen has access to the healthcare they need.")

    if preferences.get('environment'):
        messaging.append("We are committed to protecting the environment and ensuring a sustainable future for all, and we will work to reduce our carbon footprint and promote renewable energy.")

    if preferences.get('immigration'):
        messaging.append("We are committed to ensuring that all immigrants are treated with dignity and respect, and we will work to create a more inclusive and welcoming society.")

    if preferences.get('security'):
        messaging.append("We are committed to ensuring the safety and security of all citizens, and we will work to address the challenges of crime and terrorism.")

    return messaging
